@page "/settings"
@rendermode InteractiveServer
@using sv_721c33f0e1994cda9ee127e8f542e0ff.Services
@inject ISettingsService SettingsService

<PageTitle>Settings</PageTitle>

<div class="settings-layout">
    @* ── Left sidebar navigation ── *@
    <nav class="settings-sidebar">
        <h3 class="sidebar-title">Settings</h3>
        <ul class="sidebar-nav">
            @foreach (var section in _sections)
            {
                <li class="@(_activeSection == section.Key ? "active" : "")"
                    @onclick="() => SetActiveSection(section.Key)">
                    <span class="nav-icon">@section.Value.Icon</span>
                    <span>@section.Value.Label</span>
                </li>
            }
        </ul>
    </nav>

    @* ── Main content area ── *@
    <div class="settings-content">
        @if (_loading)
        {
            <div class="loading-spinner">
                <div class="spinner"></div>
                <p>Loading settings…</p>
            </div>
        }
        else
        {
            @* ── Toast message ── *@
            @if (_toastVisible)
            {
                <div class="toast-message @_toastType">
                    <span>@_toastMessage</span>
                    <button class="toast-close" @onclick="DismissToast">✕</button>
                </div>
            }

            @switch (_activeSection)
            {
                case "profile":
                    @RenderProfileSection()
                    break;
                case "notifications":
                    @RenderNotificationsSection()
                    break;
                case "security":
                    @RenderSecuritySection()
                    break;
                case "appearance":
                    @RenderAppearanceSection()
                    break;
            }
        }
    </div>
</div>

@* ── Confirmation dialog overlay ── *@
@if (_confirmDialogVisible)
{
    <div class="dialog-overlay" @onclick="CancelConfirmDialog">
        <div class="confirm-dialog" @onclick:stopPropagation>
            <h4>Revoke Session</h4>
            <p>Are you sure you want to revoke the session on <strong>@_sessionToRevoke?.Device</strong>?
               This will sign out that device immediately.</p>
            <div class="dialog-actions">
                <button class="btn btn-secondary" @onclick="CancelConfirmDialog">Cancel</button>
                <button class="btn btn-danger" @onclick="ConfirmRevokeSession">Revoke</button>
            </div>
        </div>
    </div>
}

