{"file_text": "@page "/settings"
@rendermode InteractiveServer
@using sv_721c33f0e1994cda9ee127e8f542e0ff.Services
@inject ISettingsService SettingsService

<PageTitle>Settings</PageTitle>

<div class="settings-layout">
    @* ── Left sidebar navigation ── *@
    <nav class="settings-sidebar">
        <h3 class="sidebar-title">Settings</h3>
        <ul class="sidebar-nav">
            @foreach (var section in _sections)
            {
                <li class="@(_activeSection == section.Key ? "active" : "")"
                    @onclick="() => SetActiveSection(section.Key)">
                    <span class="nav-icon">@section.Value.Icon</span>
                    <span>@section.Value.Label</span>
                </li>
            }
        </ul>
    </nav>

    @* ── Main content area ── *@
    <div class="settings-content">
        @if (_loading)
        {
            <div class="loading-spinner">
                <div class="spinner"></div>
                <p>Loading settings…</p>
            </div>
        }
        else
        {
            @* ── Toast message ── *@
            @if (_toastVisible)
            {
                <div class="toast-message @_toastType">
                    <span>@_toastMessage</span>
                    <button class="toast-close" @onclick="DismissToast">✕</button>
                </div>
            }

            @switch (_activeSection)
            {
                case "profile":
                    @RenderProfileSection()
                    break;
                case "notifications":
                    @RenderNotificationsSection()
                    break;
                case "security":
                    @RenderSecuritySection()
                    break;
                case "appearance":
                    @RenderAppearanceSection()
                    break;
            }
        }
    </div>
</div>

@* ── Confirmation dialog overlay ── *@
@if (_confirmDialogVisible)
{
    <div class="dialog-overlay" @onclick="CancelConfirmDialog">
        <div class="confirm-dialog" @onclick:stopPropagation>
            <h4>Revoke Session</h4>
            <p>Are you sure you want to revoke the session on <strong>@_sessionToRevoke?.Device</strong>?
               This will sign out that device immediately.</p>
            <div class="dialog-actions">
                <button class="btn btn-secondary" @onclick="CancelConfirmDialog">Cancel</button>
                <button class="btn btn-danger" @onclick="ConfirmRevokeSession">Revoke</button>
            </div>
        </div>
    </div>
}

@* ═══════════════════════════════════════════
   PROFILE SECTION
   ═══════════════════════════════════════════ *@
@{
    RenderFragment RenderProfileSection() =>
        @<section class="settings-section">
            <h2>Profile</h2>
            <p class="section-description">Manage your public profile information.</p>

            <div class="avatar-area">
                <img src="@_editAvatarUrl" alt="Avatar preview" class="avatar-preview" />
                <span class="avatar-url-label">@_editAvatarUrl</span>
            </div>

            <div class="form-group">
                <label for="displayName">Display Name</label>
                <input id="displayName" type="text" class="form-control"
                       @bind="_editDisplayName" @bind:event="oninput" />
            </div>

            <div class="form-group">
                <label for="email">Email</label>
                <input id="email" type="email" class="form-control"
                       @bind="_editEmail" @bind:event="oninput" />
            </div>

            <div class="form-group">
                <label for="bio">Bio</label>
                <textarea id="bio" class="form-control" rows="4"
                          @bind="_editBio" @bind:event="oninput"></textarea>
            </div>

            <div class="form-actions">
                <button class="btn btn-primary" @onclick="SaveProfile" disabled="@_saving">
                    @(_saving ? "Saving…" : "Save Changes")
                </button>
                <button class="btn btn-secondary" @onclick="DiscardProfileChanges">Discard Changes</button>
            </div>
        </section>;
}

@* ═══════════════════════════════════════════
   NOTIFICATIONS SECTION
   ═══════════════════════════════════════════ *@
@{
    RenderFragment RenderNotificationsSection() =>
        @<section class="settings-section">
            <h2>Notifications</h2>
            <p class="section-description">Choose how and when you want to be notified.</p>

            <div class="toggle-group">
                <label class="toggle-row">
                    <span>Email Notifications</span>
                    <label class="switch">
                        <input type="checkbox" @bind="_editEmailNotifications" />
                        <span class="slider"></span>
                    </label>
                </label>

                <label class="toggle-row">
                    <span>Push Notifications</span>
                    <label class="switch">
                        <input type="checkbox" @bind="_editPushNotifications" />
                        <span class="slider"></span>
                    </label>
                </label>

                <label class="toggle-row">
                    <span>Weekly Digest</span>
                    <label class="switch">
                        <input type="checkbox" @bind="_editWeeklyDigest" />
                        <span class="slider"></span>
                    </label>
                </label>
            </div>

            <h4 class="subsection-title">Muted Channels</h4>
            <p class="section-description">Check channels you want to mute.</p>
            <div class="channel-list">
                @if (_allChannels is not null)
                {
                    @foreach (var channel in _allChannels)
                    {
                        var ch = channel;
                        <label class="channel-item">
                            <input type="checkbox"
                                   checked="@_editMutedChannels.Contains(ch)"
                                   @onchange="e => ToggleMutedChannel(ch, (bool)(e.Value ?? false))" />
                            <span>#@ch</span>
                        </label>
                    }
                }
            </div>

            <div class="form-actions">
                <button class="btn btn-primary" @onclick="SaveNotificationPrefs" disabled="@_saving">
                    @(_saving ? "Saving…" : "Save Preferences")
                </button>
            </div>
        </section>;
}

@* ═══════════════════════════════════════════
   SECURITY SECTION
   ═══════════════════════════════════════════ *@
@{
    RenderFragment RenderSecuritySection() =>
        @<section class="settings-section">
            <h2>Security</h2>
            <p class="section-description">Manage your account security and active sessions.</p>

            @* ── Change Password Panel ── *@
            <div class="expandable-panel">
                <button class="panel-header" @onclick="() => _passwordPanelOpen = !_passwordPanelOpen">
                    <span>Change Password</span>
                    <span class="chevron @(_passwordPanelOpen ? "open" : "")">▸</span>
                </button>
                @if (_passwordPanelOpen)
                {
                    <div class="panel-body">
                        <div class="form-group">
                            <label for="currentPassword">Current Password</label>
                            <input id="currentPassword" type="password" class="form-control"
                                   @bind="_currentPassword" />
                        </div>
                        <div class="form-group">
                            <label for="newPassword">New Password</label>
                            <input id="newPassword" type="password" class="form-control"
                                   @bind="_newPassword" />
                        </div>
                        <div class="form-group">
                            <label for="confirmPassword">Confirm Password</label>
                            <input id="confirmPassword" type="password" class="form-control"
                                   @bind="_confirmPassword" />
                        </div>
                        @if (!string.IsNullOrEmpty(_passwordError))
                        {
                            <p class="field-error">@_passwordError</p>
                        }
                        <button class="btn btn-primary" @onclick="UpdatePassword" disabled="@_saving">
                            @(_saving ? "Updating…" : "Update Password")
                        </button>
                    </div>
                }
            </div>

            @* ── Two-Factor Authentication ── *@
            <div class="toggle-group" style="margin-top:1.5rem;">
                <label class="toggle-row">
                    <span>
                        Two-Factor Authentication
                        <span class="status-badge @(_twoFactorEnabled ? "enabled" : "disabled")">
                            @(_twoFactorEnabled ? "Enabled" : "Disabled")
                        </span>
                    </span>
                    <label class="switch">
                        <input type="checkbox" @bind="_twoFactorEnabled" />
                        <span class="slider"></span>
                    </label>
                </label>
            </div>

            @if (_security?.LastPasswordChange is not null)
            {
                <p class="meta-info">
                    Last password change: @_security.LastPasswordChange.Value.ToString("MMMM d, yyyy")
                </p>
            }

            @* ── Active Sessions Table ── *@
            <h4 class="subsection-title" style="margin-top:2rem;">Active Sessions</h4>
            @if (_security?.Sessions is { Count: > 0 })
            {
                <div class="table-wrapper">
                    <table class="sessions-table">
                        <thead>
                            <tr>
                                <th>Device</th>
                                <th>Location</th>
                                <th>Last Active</th>
                                <th></th>
                            </tr>
                        </thead>
                        <tbody>
                            @foreach (var session in _security.Sessions)
                            {
                                var isCurrent = session.Id == _security.Sessions[0].Id;
                                <tr>
                                    <td>
                                        @session.Device
                                        @if (isCurrent)
                                        {
                                            <span class="current-badge">Current</span>
                                        }
                                    </td>
                                    <td>@session.Location</td>
                                    <td>@FormatLastActive(session.LastActive)</td>
                                    <td>
                                        @if (!isCurrent)
                                        {
                                            <button class="btn btn-sm btn-danger"
                                                    @onclick="() => ShowRevokeConfirmation(session)">
                                                Revoke
                                            </button>
                                        }
                                    </td>
                                </tr>
                            }
                        </tbody>
                    </table>
                </div>
            }
        </section>;
}

@* ═══════════════════════════════════════════
   APPEARANCE SECTION
   ═══════════════════════════════════════════ *@
@{
    RenderFragment RenderAppearanceSection() =>
        @<section class="settings-section">
            <h2>Appearance</h2>
            <p class="section-description">Customize how the application looks and feels.</p>

            <div class="form-group">
                <label class="group-label">Theme</label>
                <div class="radio-group">
                    @foreach (var theme in new[] { "Light", "Dark", "System" })
                    {
                        var t = theme;
                        <label class="radio-item">
                            <input type="radio" name="theme" value="@t"
                                   checked="@(_editTheme == t)"
                                   @onchange="() => _editTheme = t" />
                            <span>@t</span>
                        </label>
                    }
                </div>
            </div>

            <div class="form-group">
                <label class="group-label">Font Size</label>
                <div class="radio-group">
                    @foreach (var size in new[] { "Small", "Medium", "Large" })
                    {
                        var s = size;
                        <label class="radio-item">
                            <input type="radio" name="fontSize" value="@s"
                                   checked="@(_editFontSize == s)"
                                   @onchange="() => _editFontSize = s" />
                            <span>@s</span>
                        </label>
                    }
                </div>
            </div>

            <div class="form-group">
                <label for="language">Language</label>
                <select id="language" class="form-control" @bind="_editLanguage">
                    <option value="English">English</option>
                    <option value="Spanish">Spanish</option>
                    <option value="French">French</option>
                    <option value="German">German</option>
                    <option value="Japanese">Japanese</option>
                    <option value="Portuguese">Portuguese</option>
                </select>
            </div>

            <div class="toggle-group">
                <label class="toggle-row">
                    <span>Compact Mode</span>
                    <label class="switch">
                        <input type="checkbox" @bind="_editCompactMode" />
                        <span class="slider"></span>
                    </label>
                </label>
            </div>

            @* ── Live Preview ── *@
            <h4 class="subsection-title">Preview</h4>
            <div class="appearance-preview @(_editTheme.ToLowerInvariant()) @(_editCompactMode ? "compact" : "")"
                 style="font-size:@GetPreviewFontSize()">
                <div class="preview-header">Sample Header</div>
                <p class="preview-body">
                    This is a preview of your selected appearance settings.
                    The theme is <strong>@_editTheme</strong>, font size is <strong>@_editFontSize</strong>,
                    and compact mode is <strong>@(_editCompactMode ? "on" : "off")</strong>.
                </p>
                <button class="preview-button">Sample Button</button>
            </div>

            <div class="form-actions">
                <button class="btn btn-primary" @onclick="SaveAppearance" disabled="@_saving">
                    @(_saving ? "Saving…" : "Save")
                </button>
            </div>
        </section>;
}

@code {
    // ── Section navigation ──
    private record SectionInfo(string Icon, string Label);

    private readonly Dictionary<string, SectionInfo> _sections = new()
    {
        ["profile"] = new("👤", "Profile"),
        ["notifications"] = new("🔔", "Notifications"),
        ["security"] = new("🔒", "Security"),
        ["appearance"] = new("🎨", "Appearance"),
    };

    private string _activeSection = "profile";
    private bool _loading = true;
    private bool _saving;

    // ── Toast ──
    private bool _toastVisible;
    private string _toastMessage = "";
    private string _toastType = "success";
    private CancellationTokenSource? _toastCts;

    // ── Profile state ──
    private UserProfile? _savedProfile;
    private string _editDisplayName = "";
    private string _editEmail = "";
    private string _editAvatarUrl = "";
    private string _editBio = "";

    // ── Notifications state ──
    private NotificationPrefs? _savedNotificationPrefs;
    private bool _editEmailNotifications;
    private bool _editPushNotifications;
    private bool _editWeeklyDigest;
    private HashSet<string> _editMutedChannels = [];
    private List<string>? _allChannels;

    // ── Security state ──
    private SecuritySettings? _security;
    private bool _twoFactorEnabled;
    private bool _passwordPanelOpen;
    private string _currentPassword = "";
    private string _newPassword = "";
    private string _confirmPassword = "";
    private string? _passwordError;

    // ── Confirmation dialog ──
    private bool _confirmDialogVisible;
    private ActiveSession? _sessionToRevoke;

    // ── Appearance state ──
    private string _editTheme = "Light";
    private string _editFontSize = "Medium";
    private string _editLanguage = "English";
    private bool _editCompactMode;

    protected override async Task OnInitializedAsync()
    {
        await LoadAllSettings();
        _loading = false;
    }

    private async Task LoadAllSettings()
    {
        var profileTask = SettingsService.GetProfileAsync();
        var notifsTask = SettingsService.GetNotificationPrefsAsync();
        var securityTask = SettingsService.GetSecuritySettingsAsync();
        var appearanceTask = SettingsService.GetAppearanceAsync();

        await Task.WhenAll(profileTask, notifsTask, securityTask, appearanceTask);

        // Profile
        _savedProfile = profileTask.Result;
        PopulateProfileFields(_savedProfile);

        // Notifications
        _savedNotificationPrefs = notifsTask.Result;
        PopulateNotificationFields(_savedNotificationPrefs);

        // Security
        _security = securityTask.Result;
        _twoFactorEnabled = _security.TwoFactorEnabled;

        // Appearance
        var appearance = appearanceTask.Result;
        _editTheme = appearance.Theme;
        _editFontSize = appearance.FontSize;
        _editLanguage = appearance.Language;
        _editCompactMode = appearance.CompactMode;
    }

    // ── Navigation ──
    private void SetActiveSection(string section)
    {
        _activeSection = section;
        DismissToast();
    }

    // ── Toast helpers ──
    private async Task ShowToast(string message, string type = "success")
    {
        _toastCts?.Cancel();
        _toastCts = new CancellationTokenSource();
        _toastMessage = message;
        _toastType = type;
        _toastVisible = true;
        StateHasChanged();

        try
        {
            await Task.Delay(4000, _toastCts.Token);
            _toastVisible = false;
            StateHasChanged();
        }
        catch (TaskCanceledException) { }
    }

    private void DismissToast()
    {
        _toastCts?.Cancel();
        _toastVisible = false;
    }

    // ── Profile ──
    private void PopulateProfileFields(UserProfile profile)
    {
        _editDisplayName = profile.DisplayName;
        _editEmail = profile.Email;
        _editAvatarUrl = profile.AvatarUrl;
        _editBio = profile.Bio;
    }

    private async Task SaveProfile()
    {
        _saving = true;
        var updated = new UserProfile(_editDisplayName, _editEmail, _editAvatarUrl, _editBio);
        await SettingsService.SaveProfileAsync(updated);
        _savedProfile = updated;
        _saving = false;
        await ShowToast("Profile saved successfully!");
    }

    private void DiscardProfileChanges()
    {
        if (_savedProfile is not null)
            PopulateProfileFields(_savedProfile);
    }

    // ── Notifications ──
    private void PopulateNotificationFields(NotificationPrefs prefs)
    {
        _editEmailNotifications = prefs.EmailNotifications;
        _editPushNotifications = prefs.PushNotifications;
        _editWeeklyDigest = prefs.WeeklyDigest;
        _editMutedChannels = [.. prefs.MutedChannels];
        _allChannels = [.. prefs.MutedChannels];
    }

    private void ToggleMutedChannel(string channel, bool muted)
    {
        if (muted) _editMutedChannels.Add(channel);
        else _editMutedChannels.Remove(channel);
    }

    private async Task SaveNotificationPrefs()
    {
        _saving = true;
        var updated = new NotificationPrefs(
            _editEmailNotifications, _editPushNotifications, _editWeeklyDigest,
            _editMutedChannels.ToList());
        await SettingsService.SaveNotificationPrefsAsync(updated);
        _savedNotificationPrefs = updated;
        _saving = false;
        await ShowToast("Notification preferences saved!");
    }

    // ── Security ──
    private async Task UpdatePassword()
    {
        _passwordError = null;

        if (string.IsNullOrWhiteSpace(_currentPassword))
        {
            _passwordError = "Current password is required.";
            return;
        }
        if (string.IsNullOrWhiteSpace(_newPassword) || _newPassword.Length < 8)
        {
            _passwordError = "New password must be at least 8 characters.";
            return;
        }
        if (_newPassword != _confirmPassword)
        {
            _passwordError = "Passwords do not match.";
            return;
        }

        _saving = true;
        await SettingsService.ChangePasswordAsync(_currentPassword, _newPassword);
        _currentPassword = "";
        _newPassword = "";
        _confirmPassword = "";
        _passwordPanelOpen = false;
        _saving = false;
        await ShowToast("Password updated successfully!");
    }

    private void ShowRevokeConfirmation(ActiveSession session)
    {
        _sessionToRevoke = session;
        _confirmDialogVisible = true;
    }

    private void CancelConfirmDialog()
    {
        _confirmDialogVisible = false;
        _sessionToRevoke = null;
    }

    private async Task ConfirmRevokeSession()
    {
        if (_sessionToRevoke is null) return;

        await SettingsService.RevokeSessionAsync(_sessionToRevoke.Id);
        _security = await SettingsService.GetSecuritySettingsAsync();
        _confirmDialogVisible = false;
        _sessionToRevoke = null;
        await ShowToast("Session revoked.");
    }

    // ── Appearance ──
    private async Task SaveAppearance()
    {
        _saving = true;
        var updated = new AppearanceSettings(_editTheme, _editFontSize, _editLanguage, _editCompactMode);
        await SettingsService.SaveAppearanceAsync(updated);
        _saving = false;
        await ShowToast("Appearance settings saved!");
    }

    private string GetPreviewFontSize() => _editFontSize switch
    {
        "Small" => "0.85rem",
        "Large" => "1.15rem",
        _ => "1rem"
    };

    private static string FormatLastActive(DateTime dt)
    {
        var diff = DateTime.UtcNow - dt;
        if (diff.TotalMinutes < 1) return "Just now";
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes}m ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours}h ago";
        return $"{(int)diff.TotalDays}d ago";
    }
}
