{"file_text": "/* ═══════════════════════════════════════
   Settings Page — Scoped Styles
   ═══════════════════════════════════════ */

/* ── Layout ── */
.settings-layout {
    display: flex;
    min-height: calc(100vh - 4rem);
    gap: 0;
}

/* ── Sidebar ── */
.settings-sidebar {
    width: 240px;
    min-width: 240px;
    background: #f8f9fa;
    border-right: 1px solid #dee2e6;
    padding: 1.5rem 0;
}

.sidebar-title {
    font-size: 1.1rem;
    font-weight: 600;
    padding: 0 1.25rem 1rem;
    margin: 0;
    color: #495057;
    letter-spacing: 0.02em;
}

.sidebar-nav {
    list-style: none;
    margin: 0;
    padding: 0;
}

.sidebar-nav li {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    padding: 0.75rem 1.25rem;
    cursor: pointer;
    color: #495057;
    font-weight: 500;
    transition: background 0.15s, color 0.15s;
    border-left: 3px solid transparent;
}

.sidebar-nav li:hover {
    background: #e9ecef;
    color: #212529;
}

.sidebar-nav li.active {
    background: #e7f1ff;
    color: #0d6efd;
    border-left-color: #0d6efd;
    font-weight: 600;
}

.nav-icon {
    font-size: 1.15rem;
}

/* ── Content Area ── */
.settings-content {
    flex: 1;
    padding: 2rem 2.5rem;
    max-width: 800px;
}

.settings-section h2 {
    font-size: 1.5rem;
    font-weight: 600;
    margin: 0 0 0.25rem;
    color: #212529;
}

.section-description {
    color: #6c757d;
    margin: 0 0 1.5rem;
    font-size: 0.925rem;
}

.subsection-title {
    font-size: 1rem;
    font-weight: 600;
    margin: 1.5rem 0 0.5rem;
    color: #343a40;
}

/* ── Loading ── */
.loading-spinner {
    display: flex;
    flex-direction: column;
    align-items: center;
    padding: 4rem 0;
    color: #6c757d;
}

.spinner {
    width: 36px;
    height: 36px;
    border: 3px solid #dee2e6;
    border-top-color: #0d6efd;
    border-radius: 50%;
    animation: spin 0.8s linear infinite;
    margin-bottom: 1rem;
}

@keyframes spin {
    to { transform: rotate(360deg); }
}

/* ── Toast ── */
.toast-message {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 0.75rem 1rem;
    border-radius: 6px;
    margin-bottom: 1.5rem;
    font-size: 0.9rem;
    animation: slideDown 0.25s ease-out;
}

.toast-message.success {
    background: #d1e7dd;
    color: #0f5132;
    border: 1px solid #badbcc;
}

.toast-message.error {
    background: #f8d7da;
    color: #842029;
    border: 1px solid #f5c2c7;
}

.toast-close {
    background: none;
    border: none;
    cursor: pointer;
    font-size: 1rem;
    line-height: 1;
    color: inherit;
    opacity: 0.7;
    padding: 0 0 0 1rem;
}

.toast-close:hover {
    opacity: 1;
}

@keyframes slideDown {
    from { opacity: 0; transform: translateY(-10px); }
    to   { opacity: 1; transform: translateY(0); }
}

/* ── Form Controls ── */
.form-group {
    margin-bottom: 1.25rem;
}

.form-group label,
.group-label {
    display: block;
    font-weight: 500;
    margin-bottom: 0.35rem;
    color: #343a40;
    font-size: 0.925rem;
}

.form-control {
    width: 100%;
    padding: 0.5rem 0.75rem;
    font-size: 0.95rem;
    border: 1px solid #ced4da;
    border-radius: 6px;
    transition: border-color 0.15s;
    box-sizing: border-box;
}

.form-control:focus {
    outline: none;
    border-color: #86b7fe;
    box-shadow: 0 0 0 3px rgba(13, 110, 253, 0.15);
}

textarea.form-control {
    resize: vertical;
}

select.form-control {
    appearance: auto;
}

.form-actions {
    display: flex;
    gap: 0.75rem;
    margin-top: 1.5rem;
    padding-top: 1.5rem;
    border-top: 1px solid #e9ecef;
}

/* ── Buttons ── */
.btn {
    padding: 0.5rem 1.25rem;
    border-radius: 6px;
    font-size: 0.925rem;
    font-weight: 500;
    border: 1px solid transparent;
    cursor: pointer;
    transition: background 0.15s, opacity 0.15s;
}

.btn:disabled {
    opacity: 0.65;
    cursor: not-allowed;
}

.btn-primary {
    background: #0d6efd;
    color: #fff;
    border-color: #0d6efd;
}

.btn-primary:hover:not(:disabled) {
    background: #0b5ed7;
}

.btn-secondary {
    background: #fff;
    color: #495057;
    border-color: #ced4da;
}

.btn-secondary:hover:not(:disabled) {
    background: #e9ecef;
}

.btn-danger {
    background: #dc3545;
    color: #fff;
    border-color: #dc3545;
}

.btn-danger:hover:not(:disabled) {
    background: #bb2d3b;
}

.btn-sm {
    padding: 0.3rem 0.75rem;
    font-size: 0.825rem;
}

/* ── Avatar ── */
.avatar-area {
    display: flex;
    align-items: center;
    gap: 1rem;
    margin-bottom: 1.5rem;
    padding: 1rem;
    background: #f8f9fa;
    border-radius: 8px;
}

.avatar-preview {
    width: 72px;
    height: 72px;
    border-radius: 50%;
    object-fit: cover;
    border: 2px solid #dee2e6;
}

.avatar-url-label {
    font-size: 0.825rem;
    color: #6c757d;
    word-break: break-all;
}

/* ── Toggle Switch ── */
.toggle-group {
    display: flex;
    flex-direction: column;
    gap: 0;
}

.toggle-row {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 0.85rem 0;
    border-bottom: 1px solid #f0f0f0;
    cursor: default;
    font-weight: 400;
}

.switch {
    position: relative;
    display: inline-block;
    width: 44px;
    height: 24px;
    flex-shrink: 0;
}

.switch input {
    opacity: 0;
    width: 0;
    height: 0;
}

.slider {
    position: absolute;
    cursor: pointer;
    inset: 0;
    background: #ccc;
    border-radius: 24px;
    transition: background 0.2s;
}

.slider::before {
    content: "";
    position: absolute;
    height: 18px;
    width: 18px;
    left: 3px;
    bottom: 3px;
    background: #fff;
    border-radius: 50%;
    transition: transform 0.2s;
}

.switch input:checked + .slider {
    background: #0d6efd;
}

.switch input:checked + .slider::before {
    transform: translateX(20px);
}

/* ── Channel list ── */
.channel-list {
    display: flex;
    flex-wrap: wrap;
    gap: 0.5rem;
    margin-top: 0.5rem;
}

.channel-item {
    display: flex;
    align-items: center;
    gap: 0.4rem;
    padding: 0.4rem 0.75rem;
    background: #f8f9fa;
    border: 1px solid #dee2e6;
    border-radius: 20px;
    font-size: 0.875rem;
    cursor: pointer;
    transition: background 0.15s;
}

.channel-item:hover {
    background: #e9ecef;
}

.channel-item input[type="checkbox"] {
    accent-color: #0d6efd;
}

/* ── Expandable Panel ── */
.expandable-panel {
    border: 1px solid #dee2e6;
    border-radius: 8px;
    overflow: hidden;
}

.panel-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    width: 100%;
    padding: 0.85rem 1rem;
    background: #f8f9fa;
    border: none;
    cursor: pointer;
    font-weight: 500;
    font-size: 0.95rem;
    color: #343a40;
    transition: background 0.15s;
}

.panel-header:hover {
    background: #e9ecef;
}

.chevron {
    display: inline-block;
    transition: transform 0.2s;
    font-size: 1rem;
}

.chevron.open {
    transform: rotate(90deg);
}

.panel-body {
    padding: 1.25rem 1rem;
    border-top: 1px solid #dee2e6;
}

.field-error {
    color: #dc3545;
    font-size: 0.85rem;
    margin: 0.25rem 0 0.75rem;
}

/* ── Status badges ── */
.status-badge {
    display: inline-block;
    font-size: 0.75rem;
    padding: 0.15rem 0.5rem;
    border-radius: 12px;
    font-weight: 600;
    margin-left: 0.5rem;
    vertical-align: middle;
}

.status-badge.enabled {
    background: #d1e7dd;
    color: #0f5132;
}

.status-badge.disabled {
    background: #f8d7da;
    color: #842029;
}

.meta-info {
    font-size: 0.85rem;
    color: #6c757d;
    margin-top: 0.75rem;
}

.current-badge {
    display: inline-block;
    font-size: 0.7rem;
    background: #cfe2ff;
    color: #084298;
    padding: 0.1rem 0.4rem;
    border-radius: 10px;
    margin-left: 0.4rem;
    font-weight: 600;
}

/* ── Sessions Table ── */
.table-wrapper {
    overflow-x: auto;
}

.sessions-table {
    width: 100%;
    border-collapse: collapse;
    font-size: 0.9rem;
}

.sessions-table th {
    text-align: left;
    padding: 0.65rem 0.75rem;
    background: #f8f9fa;
    border-bottom: 2px solid #dee2e6;
    color: #495057;
    font-weight: 600;
    font-size: 0.825rem;
    text-transform: uppercase;
    letter-spacing: 0.03em;
}

.sessions-table td {
    padding: 0.65rem 0.75rem;
    border-bottom: 1px solid #f0f0f0;
    color: #343a40;
}

.sessions-table tbody tr:hover {
    background: #f8f9fa;
}

/* ── Radio Group ── */
.radio-group {
    display: flex;
    gap: 1.25rem;
    margin-top: 0.25rem;
}

.radio-item {
    display: flex;
    align-items: center;
    gap: 0.35rem;
    cursor: pointer;
    font-size: 0.925rem;
}

.radio-item input[type="radio"] {
    accent-color: #0d6efd;
}

/* ── Appearance Preview ── */
.appearance-preview {
    margin-top: 0.75rem;
    padding: 1.25rem;
    border-radius: 8px;
    border: 1px solid #dee2e6;
    transition: all 0.25s;
}

.appearance-preview.light {
    background: #ffffff;
    color: #212529;
}

.appearance-preview.dark {
    background: #1e1e2e;
    color: #e0e0e0;
    border-color: #444;
}

.appearance-preview.system {
    background: linear-gradient(135deg, #ffffff 50%, #1e1e2e 50%);
    color: #212529;
    border-color: #aaa;
}

.appearance-preview.compact {
    padding: 0.65rem 1rem;
    line-height: 1.3;
}

.preview-header {
    font-size: 1.15em;
    font-weight: 600;
    margin-bottom: 0.5rem;
}

.preview-body {
    margin-bottom: 0.75rem;
    line-height: 1.5;
}

.preview-button {
    padding: 0.4rem 1rem;
    border-radius: 6px;
    border: none;
    font-weight: 500;
    cursor: default;
    font-size: 0.9em;
}

.appearance-preview.light .preview-button,
.appearance-preview.system .preview-button {
    background: #0d6efd;
    color: #fff;
}

.appearance-preview.dark .preview-button {
    background: #6ea8fe;
    color: #1e1e2e;
}

/* ── Confirmation Dialog ── */
.dialog-overlay {
    position: fixed;
    inset: 0;
    background: rgba(0, 0, 0, 0.45);
    display: flex;
    align-items: center;
    justify-content: center;
    z-index: 1000;
    animation: fadeIn 0.15s;
}

.confirm-dialog {
    background: #fff;
    border-radius: 10px;
    padding: 1.75rem;
    max-width: 420px;
    width: 90%;
    box-shadow: 0 8px 30px rgba(0, 0, 0, 0.2);
    animation: scaleIn 0.2s ease-out;
}

.confirm-dialog h4 {
    margin: 0 0 0.75rem;
    font-size: 1.15rem;
    color: #212529;
}

.confirm-dialog p {
    color: #495057;
    font-size: 0.925rem;
    line-height: 1.5;
    margin: 0 0 1.25rem;
}

.dialog-actions {
    display: flex;
    justify-content: flex-end;
    gap: 0.75rem;
}

@keyframes fadeIn {
    from { opacity: 0; }
    to   { opacity: 1; }
}

@keyframes scaleIn {
    from { transform: scale(0.95); opacity: 0; }
    to   { transform: scale(1); opacity: 1; }
}
