+    border-radius: 24px;
+    transition: background 0.2s;
+}
+
+.slider::before {
+    content: "";
+    position: absolute;
+    height: 18px;
+    width: 18px;
+    left: 3px;
+    bottom: 3px;
+    background: #fff;
+    border-radius: 50%;
+    transition: transform 0.2s;
+}
+
+.switch input:checked + .slider {
+    background: #0d6efd;
+}
+
+.switch input:checked + .slider::before {
+    transform: translateX(20px);
+}
+
+/* ── Channel list ── */
+.channel-list {
+    display: flex;
+    flex-wrap: wrap;
+    gap: 0.5rem;
+    margin-top: 0.5rem;
+}
+
+.channel-item {
+    display: flex;
+    align-items: center;
+    gap: 0.4rem;
+    padding: 0.4rem 0.75rem;
+    background: #f8f9fa;
+    border: 1px solid #dee2e6;
+    border-radius: 20px;
+    font-size: 0.875rem;
+    cursor: pointer;
+    transition: background 0.15s;
+}
+
+.channel-item:hover {
+    background: #e9ecef;
+}
+
+.channel-item input[type="checkbox"] {
+    accent-color: #0d6efd;
+}
+
+/* ── Expandable Panel ── */
+.expandable-panel {
+    border: 1px solid #dee2e6;
+    border-radius: 8px;
+    overflow: hidden;
+}
+
+.panel-header {
+    display: flex;
+    align-items: center;
+    justify-content: space-between;
+    width: 100%;
+    padding: 0.85rem 1rem;
+    background: #f8f9fa;
+    border: none;
+    cursor: pointer;
+    font-weight: 500;
+    font-size: 0.95rem;
+    color: #343a40;
+    transition: background 0.15s;
+}
+
+.panel-header:hover {
+    background: #e9ecef;
+}
+
+.chevron {
+    display: inline-block;
+    transition: transform 0.2s;
+    font-size: 1rem;
+}
+
+.chevron.open {
+    transform: rotate(90deg);
+}
+
+.panel-body {
+    padding: 1.25rem 1rem;
+    border-top: 1px solid #dee2e6;
+}
+
+.field-error {
+    color: #dc3545;
+    font-size: 0.85rem;
+    margin: 0.25rem 0 0.75rem;
+}
+
+/* ── Status badges ── */
+.status-badge {
+    display: inline-block;
+    font-size: 0.75rem;
+    padding: 0.15rem 0.5rem;
+    border-radius: 12px;
+    font-weight: 600;
+    margin-left: 0.5rem;
+    vertical-align: middle;
+}
+
+.status-badge.enabled {
+    background: #d1e7dd;
+    color: #0f5132;
+}
+
+.status-badge.disabled {
+    background: #f8d7da;
+    color: #842029;
+}
+
+.meta-info {
+    font-size: 0.85rem;
+    color: #6c757d;
+    margin-top: 0.75rem;
+}
+
+.current-badge {
+    display: inline-block;
+    font-size: 0.7rem;
+    background: #cfe2ff;
+    color: #084298;
+    padding: 0.1rem 0.4rem;
+    border-radius: 10px;
+    margin-left: 0.4rem;
+    font-weight: 600;
+}
+
+/* ── Sessions Table ── */
+.table-wrapper {
+    overflow-x: auto;
+}
+
+.sessions-table {
+    width: 100%;
+    border-collapse: collapse;
+    font-size: 0.9rem;
+}
+
+.sessions-table th {
+    text-align: left;
+    padding: 0.65rem 0.75rem;
+    background: #f8f9fa;
+    border-bottom: 2px solid #dee2e6;
+    color: #495057;
+    font-weight: 600;
+    font-size: 0.825rem;
+    text-transform: uppercase;
+    letter-spacing: 0.03em;
+}
+
+.sessions-table td {
+    padding: 0.65rem 0.75rem;
+    border-bottom: 1px solid #f0f0f0;
+    color: #343a40;
+}
+
+.sessions-table tbody tr:hover {
+    background: #f8f9fa;
+}
+
+/* ── Radio Group ── */
+.radio-group {
+    display: flex;
+    gap: 1.25rem;
+    margin-top: 0.25rem;
+}
+
+.radio-item {
+    display: flex;
+    align-items: center;
+    gap: 0.35rem;
+    cursor: pointer;
+    font-size: 0.925rem;
+}
+
+.radio-item input[type="radio"] {
+    accent-color: #0d6efd;
+}
+
+/* ── Appearance Preview ── */
+.appearance-preview {
+    margin-top: 0.75rem;
+    padding: 1.25rem;
+    border-radius: 8px;
+    border: 1px solid #dee2e6;
+    transition: all 0.25s;
+}
+
+.appearance-preview.light {
+    background: #ffffff;
+    color: #212529;
+}
+
+.appearance-preview.dark {
+    background: #1e1e2e;
+    color: #e0e0e0;
+    border-color: #444;
+}
+
+.appearance-preview.system {
+    background: linear-gradient(135deg, #ffffff 50%, #1e1e2e 50%);
+    color: #212529;
+    border-color: #aaa;
+}
+
+.appearance-preview.compact {
+    padding: 0.65rem 1rem;
+    line-height: 1.3;
+}
+
+.preview-header {
+    font-size: 1.15em;
+    font-weight: 600;
+    margin-bottom: 0.5rem;
+}
+
+.preview-body {
+    margin-bottom: 0.75rem;
+    line-height: 1.5;
+}
+
+.preview-button {
+    padding: 0.4rem 1rem;
+    border-radius: 6px;
+    border: none;
+    font-weight: 500;
+    cursor: default;
+    font-size: 0.9em;
+}
+
+.appearance-preview.light .preview-button,
+.appearance-preview.system .preview-button {
+    background: #0d6efd;
+    color: #fff;
+}
+
+.appearance-preview.dark .preview-button {
+    background: #6ea8fe;
+    color: #1e1e2e;
+}
+
+/* ── Confirmation Dialog ── */
+.dialog-overlay {
+    position: fixed;
+    inset: 0;
+    background: rgba(0, 0, 0, 0.45);
+    display: flex;
+    align-items: center;
+    justify-content: center;
+    z-index: 1000;
+    animation: fadeIn 0.15s;
+}
+
+.confirm-dialog {
+    background: #fff;
+    border-radius: 10px;
+    padding: 1.75rem;
+    max-width: 420px;
+    width: 90%;
+    box-shadow: 0 8px 30px rgba(0, 0, 0, 0.2);
+    animation: scaleIn 0.2s ease-out;
+}
+
+.confirm-dialog h4 {
+    margin: 0 0 0.75rem;
+    font-size: 1.15rem;
+    color: #212529;
+}
+
+.confirm-dialog p {
+    color: #495057;
+    font-size: 0.925rem;
+    line-height: 1.5;
+    margin: 0 0 1.25rem;
+}
+
+.dialog-actions {
+    display: flex;
+    justify-content: flex-end;
+    gap: 0.75rem;
+}
+
+@keyframes fadeIn {
+    from { opacity: 0; }
+    to   { opacity: 1; }
+}
+
+@keyframes scaleIn {
+    from { transform: scale(0.95); opacity: 0; }
+    to   { transform: scale(1); opacity: 1; }
+}
